// Performance-Ventil (Gabriel woertlich: "Bleibt sie unter 24 fps, reduziere
// zuerst die Regenebenen -- Blinzeln und Mikrobewegung sind die letzten
// Dinge, die fallen duerfen."). Regenebenen fallen zuerst, Praesenz zuletzt --
// blinzeln()/atmen() lesen regenGedrosselt gar nicht erst.
let regenGedrosselt = false;
function tropfenErzeugenVorne(){
  const deckel = regenGedrosselt ? 35 : 100;
  if(tropfenVorne.length > deckel) return; // Deckel gegen fps-Einbruch
  tropfenVorne.push({
    x: Math.random() * canvas.width, y: -10,
    v: (0.8 + Math.random() * 1.7) * tempo,
    len: 14 + Math.random() * 26,
    ton: Math.random() < 0.5 ? "34,221,238" : "136,51,255"
  });
}
// Hintere Ebene: kleiner, langsamer, gedaempfter -- wirkt weiter weg.
function tropfenErzeugenHinten(){
  const deckel = regenGedrosselt ? 20 : 70;
  if(tropfenHinten.length > deckel) return; // insgesamt weniger als vorher (140)
  tropfenHinten.push({
    x: Math.random() * canvasHinten.width, y: -10,
    v: (0.35 + Math.random() * 0.7) * tempo,
    len: 6 + Math.random() * 12,
    ton: Math.random() < 0.5 ? "34,221,238" : "136,51,255"
  });
}
function regenZeichnenEbene(c, cv, liste, alpha, breite){
  c.clearRect(0,0,cv.width, cv.height);
  c.lineWidth = breite;
  for(const t of liste){
    c.strokeStyle = `rgba(${t.ton},${alpha})`;
    c.beginPath();
    c.moveTo(t.x, t.y);
    c.lineTo(t.x, t.y + t.len);
    c.stroke();
    t.y += t.v * 3.2;
  }
}
function regenZeichnen(){
  regenZeichnenEbene(ctx, canvas, tropfenVorne, 0.5, 1.4);
  tropfenVorne = tropfenVorne.filter(t => t.y < canvas.height + 20);
  regenZeichnenEbene(ctxHinten, canvasHinten, tropfenHinten, 0.28, 1.0);
  tropfenHinten = tropfenHinten.filter(t => t.y < canvasHinten.height + 20);
}

// Sehr langsames Atmen, an den Puls-Takt (tempo, aus broadcast_value)
// gekoppelt -- Skalierung bleibt in 1.00..1.012 (Gabriels Richtwert),
// nie darunter, damit es nie wie ein Schrumpfen wirkt.
let atemPhase = 0;
// ⭐ 2026-09-11 Punkt c der Liste ("Mikro-Variation zwischen Nachbarstufen
// DESSELBEN Ausdrucks, damit das Gesicht 'arbeitet' statt einzufrieren"):
// woertlich nicht baubar wie gefragt -- die 6 Grundstimmungen haben keine
// Stufen-Bilder (nur 1 flaches PNG je Stimmung, siehe ausdruck_zugeschnitten/)
// und werden aktuell nicht einmal als eigene Bildebene gezeichnet (siehe
// Kommentar bei gesichtNeuZeichnen() oben -- offene Luecke, schon gemeldet).
// Ein erfundenes Stufenbild waere eine erfundene Ausdrucks-AENDERUNG, keine
// Leerlaufbewegung -- verboten. Stattdessen: der GEIST des Auftrags auf dem
// bereits echten, bereits sichtbaren Atem-Puls oben -- ein winziger, LANGSAM
// und UNREGELMAESSIG wandernder Zusatz-Faktor (Random Walk, kein fester
// Takt), der die Helligkeit minimal mitzittern laesst. Kein neuer Zustand,
// keine neue Bildquelle -- nur mehr Unregelmaessigkeit auf echter, schon
// gerenderter Bewegung.
let _mikroUnruhe = 0, _mikroUnruheZiel = 0;
setInterval(() => { _mikroUnruheZiel = (Math.random()*2 - 1); }, 2600 + Math.random()*3200);
// ⭐⭐⭐ 2026-09-11 PERF-FIX (Koordinator-Auftrag, fps 35-45 statt >45, unter
// erzwungenem Software-Rendering -- siehe --disable-gpu in buehne_daemon.py,
// Grund dort dokumentiert: echter Speicherkonflikt mit llama-server -ngl 99
// auf der geteilten iGPU, PERMISSION_FAULTS/MAPPING_ERROR in dmesg, kein
// bloss abwaegbares Budget -- GPU-Kompositing bleibt deshalb AUS, dieser
// Pfad wird nicht wieder angefasst). Ursache war NICHT das Rechnen selbst
// (6x scale()+saturate()+brightness() pro Frame ist trivial), sondern dass
// atmen() bisher alle 6 Ebenen (inkl. beider "2"-Zwillinge, die 4 von 6
// Framezeiten lang komplett unsichtbar sind: kopf-schicht2 ausser waehrend
// einer Rollpose, ausdruck-schicht/-schicht2 ausser waehrend eines seltenen
// Sonderausdrucks) auf style.transform/style.filter schreiben liess --
// jeder Schreibzugriff auf transform/filter stoesst unter Software-Rendering
// eine erneute Rasterung der vollen 1536x1024-RGBA-Ebene an, UNABHAENGIG von
// opacity:0 (der Browser kompositiert die Ebene nicht sichtbar, aber die
// Filter-Pipeline muss trotzdem neu gerechnet werden, weil die Property sich
// geaendert hat). Fix: nur die AKTUELL SICHTBARE Ebene jedes Zwillingspaars
// bekommt den Schreibzugriff -- aus max. 6 Style-Writes/Frame werden 2-3 (Kopf
// + Koerper immer, Ausdruck nur waehrend _sonderLaeuft). Der urspruengliche
// Zweck dieser Zeilen (keine Stale-Werte beim naechsten Hart-Cut-Einblenden,
// siehe Kommentar am Dateianfang zu diesem Fund) bleibt vollstaendig erhalten
// -- nicht durch Weglassen geloest, sondern durch VORSYNCHRONISIEREN: die
// zuletzt berechneten Werte liegen in _atmenTransform/_atmenFilter global
// bereit, und jede Stelle, die eine bisher versteckte Zwillings-Ebene per
// opacity 0->1 sichtbar macht (koerperCrossfade(), kopfRollTick(), die
// wechsel()-Funktion in sonderausdruckZeigen()), schreibt diese Werte JETZT
// EINMALIG auf die Ebene, BEVOR sie opacity:1 bekommt -- exakt derselbe Wert,
// den atmen() diesen Frame sowieso schon fuer die bis dahin sichtbare Ebene
// gesetzt hat (schleife() ruft atmen() vor koerperSchritt()/kopfRollTick()
// auf, siehe unten -- die Werte sind also brandaktuell, kein Frame Verzug).
// Ergebnis: kein Pop (die neue Ebene traegt beim ersten sichtbaren Frame
// exakt denselben Skala-/Helligkeitswert wie ihr Zwilling im Frame davor),
// aber die vier meiste Zeit unsichtbaren Ebenen werden NICHT mehr pro Frame
// angefasst.
let _atmenTransform = "scale(1)";
let _atmenFilter = "saturate(1.05) brightness(1)";
function atmen(){
  atemPhase += 0.006 * Math.max(0.4, Math.min(1.6, tempo));
  _mikroUnruhe += (_mikroUnruheZiel - _mikroUnruhe) * 0.02; // sehr langsam, kein Sprung
  const auf = (Math.sin(atemPhase) * 0.5) + 0.5; // 0..1
  const skala = 1 + auf * 0.012;
  const helligkeit = 1 + (auf - 0.5) * 0.03 + _mikroUnruhe * 0.006;
  const transform = `scale(${skala})`;
  const filter = `saturate(1.05) brightness(${helligkeit})`;
  _atmenTransform = transform;
  _atmenFilter = filter;
  // Kopf: nur die gerade sichtbare der beiden Ebenen (kopfRollAktiv siehe
  // kopfRollTick() -- false: kopf-schicht sichtbar, true: kopf-schicht2).
  const kopfSichtbar = kopfRollAktiv ? "kopf-schicht2" : "kopf-schicht";
  $(kopfSichtbar).style.transform = transform;
  $(kopfSichtbar).style.filter = filter;
  // ⭐⭐ 2026-09-11 NACHTRAG 3 (Koordinator meldet Halsnaht-Rutschen, Gabriel
  // hat 3 Screenshots geschickt): Kopf skalierte 1.000->1.012->1.000 pro
  // Atemzug, Koerper blieb starr bei 1.0 (siehe Kommentar oben, bewusst
  // entfernt wegen "doppeltem Atmen"). Ergebnis: Kopf wird am Atem-Peak
  // relativ zum starren Koerper 1,2% groesser -- die Halskante (wo Kopf-
  // und Koerperbild sich per Masken-Verlauf treffen, siehe #kopf-schicht
  // Halsmaske oben) rutscht auf jedem Atemzug leicht -- unsichtbar im
  // Standbild (Koordinator hat das geprueft), sichtbar in Bewegung.
  // FIX (a) aus dem Koordinator-Auftrag, kleinste/sicherste Variante: der
  // Koerper bekommt DENSELBEN Transform+Filter wie der Kopf -- beide
  // skalieren/hellen im GLEICHEN Takt, die Halskante bleibt an derselben
  // Relativstelle. Der Koerper "atmet" dadurch zusaetzlich zu seinen 12
  // fotografierten Stufen leicht mit (max +1,2% Groesse) -- das ist die
  // Halskante wert; ein rutschender Kragen war das schlimmere Artefakt.
  // Nur die aktuell sichtbare Koerper-Ebene (atmenAktivSchicht, siehe
  // koerperCrossfade()) bekommt den Schreibzugriff, gleiche Begruendung wie
  // beim Kopf oben.
  $(atmenAktivSchicht).style.transform = transform;
  $(atmenAktivSchicht).style.filter = filter;
  // Ausdruck-Ebenen sind ausserhalb eines Sonderausdrucks BEIDE opacity:0 --
  // dann gibt es nichts zu synchronisieren, kein Pop-Risiko (nichts sichtbar).
  // Waehrend eines Sonderausdrucks bekommt nur die per ausdruckAktiv aktuell
  // sichtbare Ebene den Schreibzugriff (siehe sonderausdruckZeigen()/wechsel()
  // fuer die Vor-Synchronisation der jeweils anderen beim Einblenden).
  if(_sonderLaeuft){
    const ausdruckSichtbar = ausdruckAktiv === 1 ? "ausdruck-schicht" : "ausdruck-schicht2";
    $(ausdruckSichtbar).style.transform = transform;
    $(ausdruckSichtbar).style.filter = filter;
  }
}

// ⭐⭐ 2026-09-11 ECHTES KOERPER-ATMEN (Gabriel, woertlich: "eins nach dem
// anderen" -- DIE eine Sache fuer diesen Schritt, nichts anderes gleichzeitig).
// 12 echte fotografierte Atem-Stufen (koerper_rgba/atmen__atmen_000..011.png,
// laut Dateibenennung eine VOLLSTAENDIGE Ein-und-Ausatmung -- deshalb einfach
// im Kreis 0->11->0 durchlaufen, kein Hin-und-Her-Pingpong noetig) statt der
// bisherigen reinen scale()-Attrappe auf #koerper-schicht (siehe atmen() oben).
// Ueberblendet weich per Opacity-Crossfade zwischen zwei gestapelten <img>
// (#koerper-schicht/#koerper-schicht2), exakt das gleiche Muster wie
// #gesicht/#gesicht2. Gabriels Zahlen woertlich: 14-16 Atemzuege/min -> ~4s
// pro Zyklus -> ~330ms je Bild bei 12 Bildern.
// ⚠️ Speicher: NUR diese 12 Bilder werden vorgeladen, nicht die uebrigen 126
// koerper_rgba-Dateien (schulterdrehung/lehnen/gewicht/... bleiben fuer
// spaetere, einzeln freigegebene Schritte unangetastet auf Abruf).
const ATMEN_BILDER = Array.from({length:12}, (_,i) =>
  `/koerper_rgba/atmen__atmen_${String(i).padStart(3,"0")}.png`);
ATMEN_BILDER.forEach(src => { const vorlade = new Image(); vorlade.src = src; });
const ATMEN_MS_PRO_BILD = 330;
let atmenIndex = 0;
let atmenLetzterWechsel = 0;
let atmenAktivSchicht = "koerper-schicht";
function koerperCrossfade(src){
  const naechsteSchicht = atmenAktivSchicht === "koerper-schicht" ? "koerper-schicht2" : "koerper-schicht";
  $(naechsteSchicht).src = src;
  // ⭐⭐ PERF-FIX 2026-09-11: gleiche Vor-Synchronisation wie bei
  // kopfRollTick()/sonderausdruckZeigen() -- atmen() schreibt Transform/
  // Filter nur noch auf atmenAktivSchicht (die aktuell sichtbare Koerper-
  // Ebene). Bevor die naechste Ebene sichtbar wird, bekommt sie hier den
  // brandaktuellen Wert -- sonst Pop beim Umschalten.
  $(naechsteSchicht).style.transform = _atmenTransform;
  $(naechsteSchicht).style.filter = _atmenFilter;
  $(naechsteSchicht).style.opacity = 1;
  $(atmenAktivSchicht).style.opacity = 0;
  atmenAktivSchicht = naechsteSchicht;
}
// ⭐⭐ 2026-09-11 (Animations-Agent, Auftrag 4): die uebrigen echten
// Koerperbewegungen aus /koerper_rgba/ -- bisher lief nur atmen/ (12 Frames).
// ls-gepruefte Bestaende: schulterzucken 8, aufrichten 8, lehnen 9, gewicht 7,
// schulterdrehung 15 (schulter_+NN.png!), kombiniert 9. Alle als SELTENE
// Idle-Aktionen auf EINEM Spieler + EINER Scheduler-Kette (keine parallelen
// Systeme), geladen wird lazy ueber bildLaden() -- zuerst sichtbar schalten,
// wenn der Frame dekodiert ist (kein Flash). kombiniert bleibt bewusst draussen:
// seine Dateifolge (lehnen_+00_schulter_+00 / +20 / -20 ...) ist keine
// monotone Bewegungslinie, ein Durchlauf davon waere ein Sprung, keine Bewegung.
const KOERPER_AKTIONEN = [
  { name:"schulterzucken", ms:110, bilder:[0,1,2,3,4,5,6,7].map(n =>
      `/koerper_rgba/schulterzucken/zucken_${String(n).padStart(3,"0")}.png`) },
  { name:"aufrichten", ms:200, bilder:[0,1,2,3,4,5,6,7].map(n =>
      `/koerper_rgba/aufrichten/aufrichten_${String(n).padStart(3,"0")}.png`) },
  { name:"lehnen", ms:300, bilder:["lehnen_+00","lehnen_+05","lehnen_+10","lehnen_+15",
      "lehnen_+20","lehnen_+15","lehnen_+10","lehnen_+05","lehnen_+00"].map(n =>
      `/koerper_rgba/lehnen/${n}.png`) },
  { name:"gewicht", ms:300, bilder:["gewicht_+00","gewicht_+05","gewicht_+10","gewicht_+15",
      "gewicht_+10","gewicht_+05","gewicht_+00","gewicht_-05","gewicht_-10",
      "gewicht_-05","gewicht_+00"].map(n =>
      `/koerper_rgba/gewicht/${n}.png`) },
  { name:"schulterdrehung", ms:170, bilder:["schulter_+00","schulter_+05","schulter_+10",
      "schulter_+15","schulter_+10","schulter_+05","schulter_+00","schulter_-05",
      "schulter_-10","schulter_-05","schulter_+00"].map(n =>
      `/koerper_rgba/schulterdrehung/${n}.png`) }
];
let koerperAktion = null;      // {bilder, ms, idx, letzterT, fertig}
let _letzteKoerperAktion = null;
function koerperAktionStarten(fertig){
  if(koerperAktion || _sonderLaeuft){ if(fertig) fertig(); return; }
  const pool = KOERPER_AKTIONEN.filter(a => a.name !== _letzteKoerperAktion);
  const wahl = pool[Math.floor(Math.random()*pool.length)];
  _letzteKoerperAktion = wahl.name;
  koerperAktion = { bilder:wahl.bilder, ms:wahl.ms, idx:0, letzterT:0, fertig };
}
function koerperAktionWeiterPlanen(){
  // 22-50s Ruhe zwischen zwei Koerperaktionen -- selten, unregelmaessig,
  // gleiche Idee wie blinzelWeiterPlanen(): EINE Kette, die sich selbst
  // weiterreicht, kein Verzweigen.
  setTimeout(() => koerperAktionStarten(() => koerperAktionWeiterPlanen()),
    22000 + Math.random()*28000);
}
koerperAktionWeiterPlanen();
function koerperSchritt(jetzt){
  if(koerperAktion){
    const a = koerperAktion;
    if(jetzt - a.letzterT < a.ms) return;
    const eintrag = bildLaden(a.bilder[a.idx]);
    if(!eintrag.ok) return; // Frame noch nicht dekodiert -- warten statt Flash
    a.letzterT = jetzt;
    koerperCrossfade(a.bilder[a.idx]);
    a.idx++;
    if(a.idx >= a.bilder.length){
      koerperAktion = null;
      const f = a.fertig; a.fertig = null;
      if(f) f();
    }
    return;
  }
  if(jetzt - atmenLetzterWechsel < ATMEN_MS_PRO_BILD) return;
  atmenLetzterWechsel = jetzt;
  atmenIndex = (atmenIndex + 1) % ATMEN_BILDER.length;
  koerperCrossfade(ATMEN_BILDER[atmenIndex]);
}

// ⭐ 2026-09-11 (Gabriel woertlich: "als wuerde er sich selbst echt mit dem
// Handy filmen, am besten sogar ganz leicht Cam-Shake, aber realistisch
// passend zur Bewegung. Volle Immersion..."). EIN gemeinsamer Transform auf
// #kamera fuer die GESAMTE Szene (Hintergrund+Koerper+Kopf+Mund+Augen) --
// nie pro Ebene einzeln, sonst zerfaellt die Illusion sofort ("kein
// echtes Handy waere so exakt synchron mit sich selbst"). Drei
// ueberlagerte, bewusst NICHT-zufaellige Komponenten (Gabriels Vorgabe:
// gleichfoermiges Zufallsrauschen sieht nicht wie eine echte Hand aus):
//  1) langsame Drift (Atmung/Ermuedung der haltenden Hand, ~4-5s Periode,
//     wenige px) -- Fortsetzung der bisherigen "nie ganz still"-Drift,
//     jetzt auf die ganze Kamera statt nur auf #gesicht verschoben.
//  2) schnelles Mikro-Zittern (~8-12Hz, <1px) -- der Muskelzittern-Anteil
//     einer echten Hand, zwei knapp benachbarte Sinusfrequenzen statt einer
//     einzelnen, damit es nicht mechanisch/taktfest wirkt.
//  3) minimale Rotation (Bruchteile eines Grads) -- eine Hand kippt nie rein
//     linear.
// Hintergrund bewegt sich absichtlich einen Hauch WENIGER als der Rest
// (0.85x) -- winziger Parallaxe-Tiefenhinweis, siehe Koordinator ("optional:
// Hintergrund bewegt sich minimal weniger als der Vordergrund").
// ⭐⭐ 2026-09-11 RETUNE nach Gabriels Live-Urteil ("er zittert, schaut
// relativ shit aus"): die 8-10Hz-Mikrozitter-Komponente unten war zu schnell
// UND zu stark -- auf einem kleinen Panel (~296px breit), mit dem neuen
// engeren Kopf-Crop, UND auf einem Chrome-Fenster ohne GPU-Kompositing
// (--disable-gpu, siehe Fensterstart) liest sich eine 8-10Hz-Oszillation
// nicht als sanftes Handzittern, sondern als sichtbares Vibrieren/Ruckeln --
// das Auge ist fuer zeitliches Flackern empfindlicher als fuer die reine
// Pixelamplitude. Fix: Frequenz UND Amplitude aller drei Komponenten deutlich
// gesenkt (Tremor von ~10/8Hz auf ~3/2.3Hz, Drift/Rotation-Amplitude
// grob halbiert). Ziel ist jetzt spuerbar ruhiger -- lieber zu wenig als
// wieder "zittert".
let driftPhaseX = Math.random() * Math.PI * 2;
let driftPhaseY = Math.random() * Math.PI * 2;
let tremorPhaseA = Math.random() * Math.PI * 2;
let tremorPhaseB = Math.random() * Math.PI * 2;
let rotPhase = Math.random() * Math.PI * 2;
function kameraWackeln(){
  const t = Math.max(0.4, Math.min(1.6, tempo)); // "passend zur Bewegung": etwas mehr Schub bei hoeherem Tempo
  driftPhaseX += 0.0131; // ~8.0s Periode bei 60fps (war ~4.0s)
  driftPhaseY += 0.0105; // ~9.6s Periode -- absichtlich versetzt zu X (war ~4.9s)
  tremorPhaseA += 0.314;  // ~3Hz (war ~10Hz)
  tremorPhaseB += 0.251;  // ~2.4Hz, knapp daneben statt exakt gleich (war ~8Hz)
  rotPhase += 0.0063;     // ~16s Periode, noch langsamer als die Drift (war ~8.3s)
  const driftX = Math.sin(driftPhaseX) * 0.7 * t;
  const driftY = Math.cos(driftPhaseY) * 0.55 * t;
  const tremorX = (Math.sin(tremorPhaseA) * 0.14 + Math.sin(tremorPhaseB) * 0.09) * t;
  const tremorY = (Math.cos(tremorPhaseA * 0.97) * 0.12 + Math.cos(tremorPhaseB * 1.05) * 0.07) * t;
  const rotDeg = Math.sin(rotPhase) * 0.06 * t;
  const x = driftX + tremorX, y = driftY + tremorY;
  $("kamera").style.transform = `translate(${x.toFixed(2)}px, ${y.toFixed(2)}px) rotate(${rotDeg.toFixed(3)}deg)`;
  // Hintergrund bekommt denselben Wackel, aber 0.85x gedaempft -- winzige
  // Parallaxe, das Bild wirkt nicht wie eine starre Fotomontage auf dem
  // Hintergrund geklebt. #hg-frame ist Kind von #kamera -- dieser Transform
  // addiert sich zu dem der Kamera, deshalb hier bewusst der GEGEN-Anteil
  // (0.85-1 = -0.15x) statt des vollen Werts.
  $("hg-frame").style.transform = `translate(${(x*-0.15).toFixed(2)}px, ${(y*-0.15).toFixed(2)}px)`;
}
// ⭐ Nachschwung bei echten Zustandswechseln (Kopfdrehung/Ausdruck/Blick) --
// dieselbe Overshoot-Mechanik wie #gesicht-rahmen.pose-wechsel, jetzt auf
// #kamera: die Kamera "haengt" kurz nach und faengt sich dann leicht ueber,
// wie eine echte Hand, die einer Bewegung folgt (Gabriel: "passend zur
// Bewegung"). Siehe gesichtNeuZeichnen() weiter oben, ruft dies bei
// echten Zustandswechseln auf.
function kameraNachschwung(){
  const kamera = $("kamera");
  kamera.classList.remove("kamera-wechsel");
  requestAnimationFrame(() => kamera.classList.add("kamera-wechsel"));
  setTimeout(() => kamera.classList.remove("kamera-wechsel"), 420);
}

let letzteFrames = [];
function fpsMessen(t){
  letzteFrames.push(t);
  const grenze = t - 1000;
  letzteFrames = letzteFrames.filter(x => x > grenze);
  window.__buehneFps = letzteFrames.length;
}

function schleife(t){
  atmen();
  koerperSchritt(t);
  kopfRollTick(t);
  mundSchritt(t);
  kopfKoerperDrehSchritt();
  kameraWackeln();
  gazeSchritt();
  const regenFaktor = regenGedrosselt ? 0.5 : 1;
  if(Math.random() < 0.35 * tempo * regenFaktor) tropfenErzeugenVorne();
  if(Math.random() < 0.22 * tempo * regenFaktor) tropfenErzeugenHinten();
  regenZeichnen();
  fpsMessen(t);
  requestAnimationFrame(schleife);
}
requestAnimationFrame(schleife);
setInterval(() => {
  const fps = window.__buehneFps || 60;
  if(fps < 24 && !regenGedrosselt){
    regenGedrosselt = true;
    console.warn("[buehne] fps<24 -- Regenebenen gedrosselt, Blinzeln/Atem-Drift bleiben unangetastet");
  }else if(fps >= 28 && regenGedrosselt){
    regenGedrosselt = false;
  }
}, 4000);

// Selbstmeldung der gemessenen Bildrate an den eigenen Server, alle 5s --
// fuer den Belegpflicht-Test (echte Messung, keine Annahme "60fps").
setInterval(() => {
  fetch("/api/fps", {method:"POST", headers:{"Content-Type":"application/json"},
    body: JSON.stringify({fps: window.__buehneFps || 0})}).catch(()=>{});
}, 5000);
// gedrosselt auf ~20fps fuer Datenregen-Erzeugung reicht optisch, Zeichnen
// selbst laeuft mit requestAnimationFrame (typisch Bildwiederholrate des
// Monitors) -- absichtlich 2D-Canvas statt WebGL, s. Bericht (GPU-Druck).

// ── Zustand/Buehnen-Treiber alle 3s holen (kein WebSocket noetig) ───
async function statusHolen(){
  try{
    const r = await fetch("/api/status");
    const d = await r.json();
    const b = d.buehne || {};
    if(typeof b.broadcast_value === "number"){
      tempo = Math.max(0.15, Math.min(3.0, b.broadcast_value));
    }
    const farb = $("farbschicht");
    if(typeof b.ueberraschung === "number"){
      const intensitaet = Math.max(0, Math.min(1, b.ueberraschung));
      farb.style.background = `radial-gradient(ellipse at 50% 40%, rgba(136,51,255,${0.25*intensitaet}) 0%, rgba(34,221,238,${0.18*intensitaet}) 100%)`;
      farb.style.opacity = intensitaet > 0.05 ? "1" : "0";
    }
    const wasser = $("wasserlinie");
    let hoehe = null;
    if(typeof b.swap_voll_anteil === "number") hoehe = b.swap_voll_anteil;
    else if(typeof b.ram_frei_anteil === "number") hoehe = 1 - b.ram_frei_anteil;
    if(hoehe !== null){
      wasser.style.height = Math.max(0, Math.min(100, hoehe*100)) + "%";
    }
    // Auftragsteil F: Koerperkrise + Ueberraschungs-Achse, siehe Definition
    // oben (koerperzustandPruefen/ueberraschungAchsePruefen).
    koerperzustandPruefen(b.swap_voll_anteil, b.ram_frei_anteil);
    ueberraschungAchsePruefen(b.ueberraschung);
    if(typeof d.zuschauer === "number"){
      $("zuschauer-label").textContent = d.zuschauer + (d.zuschauer===1?" Zuschauer":" Zuschauer");
    }
    // Ausdruck + Blick: gemessen, nie erfunden (siehe buehnen_zustand() in
    // buehne_daemon.py bzw. blick.py). Latenz + Reihenfolge in
    // reaktionAufNeuenStatus() oben.
    reaktionAufNeuenStatus(
      b.blick || {anwesend:false, richtung:null, nah:false},
      typeof b.ausdruck === "string" ? b.ausdruck : null
    );
  }catch(e){}
}

