let _startMtime = null;
async function _reloadWaechter(){
  try{
    const r = await fetch("/api/mtime", {cache:"no-store"});
    const d = await r.json();
    if(_startMtime === null){ _startMtime = d.mtime; return; }
    if(d.mtime && d.mtime !== _startMtime){ location.reload(); }
  }catch(e){}
}
